return $input.all().map(item => ({
  json: {
    file_id: item.json.url || '',
    file_name: item.json.fileName || '',
    status: item.json.status || '',
    pages: item.json.pageCount || 0,
    characters: item.json.charCount || 0,
    text: (item.json.text || '').slice(0, 10000),
    processed_at: new Date().toISOString()
  }
}));
